import{_ as s,o as i,c as e,ae as t}from"./chunks/framework.DJIAqD5B.js";const k=JSON.parse('{"title":"JVM Arguments","description":"","frontmatter":{},"headers":[],"relativePath":"en/user-guide/jvm.md","filePath":"en/user-guide/jvm.md"}'),n={name:"en/user-guide/jvm.md"};function l(h,a,p,o,r,d){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="jvm-arguments" tabindex="-1">JVM Arguments <a class="header-anchor" href="#jvm-arguments" aria-label="Permalink to &quot;JVM Arguments&quot;">​</a></h1><h2 id="which-jvm-arguments-can-help-optimize-xiaozi-craft" tabindex="-1">Which JVM arguments can help optimize <code>xiaozi craft</code>? <a class="header-anchor" href="#which-jvm-arguments-can-help-optimize-xiaozi-craft" aria-label="Permalink to &quot;Which JVM arguments can help optimize `xiaozi craft`?&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Do not mix Java 21 arguments with Java 25+ arguments.</p></div><h3 id="java-21-arguments" tabindex="-1">Java 21 arguments <a class="header-anchor" href="#java-21-arguments" aria-label="Permalink to &quot;Java 21 arguments&quot;">​</a></h3><p>Using generational ZGC on Java 21 can improve game performance significantly.</p><div class="language-Java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">XX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">UseZGC </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">XX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ZGenerational </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">XX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AlwaysPreTouch</span></span></code></pre></div><h4 id="use-the-g1gc-memory-manager" tabindex="-1">Use the G1GC memory manager <a class="header-anchor" href="#use-the-g1gc-memory-manager" aria-label="Permalink to &quot;Use the G1GC memory manager&quot;">​</a></h4><div class="language-Java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">XX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">UseG1GC</span></span></code></pre></div><h4 id="disable-adaptive-sizing-policy" tabindex="-1">Disable adaptive sizing policy <a class="header-anchor" href="#disable-adaptive-sizing-policy" aria-label="Permalink to &quot;Disable adaptive sizing policy&quot;">​</a></h4><p>After disabling it, the JVM will no longer resize the young generation, old generation, or survivor spaces automatically. On heavily modded game servers, object promotion patterns are often predictable, so manual sizing can provide more stable GC behavior.</p><div class="language-Java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">XX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">UseAdaptiveSizePolicy</span></span></code></pre></div><h4 id="disable-the-fast-throw-optimization-that-omits-stack-traces" tabindex="-1">Disable the fast-throw optimization that omits stack traces <a class="header-anchor" href="#disable-the-fast-throw-optimization-that-omits-stack-traces" aria-label="Permalink to &quot;Disable the fast-throw optimization that omits stack traces&quot;">​</a></h4><p>The JVM may omit stack traces when the same exception is thrown repeatedly from the same location. This option forces a full stack trace every time, which is useful when debugging mod conflicts or plugin issues.</p><div class="language-Java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">XX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OmitStackTraceInFastThrow</span></span></code></pre></div><h4 id="allow-ambiguous-process-command-strings" tabindex="-1">Allow ambiguous process command strings <a class="header-anchor" href="#allow-ambiguous-process-command-strings" aria-label="Permalink to &quot;Allow ambiguous process command strings&quot;">​</a></h4><p>On Windows, <code>ProcessBuilder</code> can reject ambiguous command strings such as paths with spaces and missing quotes. This flag relaxes that behavior.</p><div class="language-Java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Djdk.lang.Process.allowAmbiguousCommands</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><h4 id="ignore-invalid-minecraft-certificates" tabindex="-1">Ignore invalid Minecraft certificates <a class="header-anchor" href="#ignore-invalid-minecraft-certificates" aria-label="Permalink to &quot;Ignore invalid Minecraft certificates&quot;">​</a></h4><p>Some mods or core modifications can break the original Minecraft jar signature checks. Enabling this option prevents crashes caused by certificate validation failures.</p><div class="language-Java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Dfml.ignoreInvalidMinecraftCertificates</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">True</span></span></code></pre></div><h4 id="ignore-mod-patch-discrepancy-warnings-and-errors" tabindex="-1">Ignore mod patch discrepancy warnings and errors <a class="header-anchor" href="#ignore-mod-patch-discrepancy-warnings-and-errors" aria-label="Permalink to &quot;Ignore mod patch discrepancy warnings and errors&quot;">​</a></h4><p>When Forge patches Minecraft classes, conflicts between mods or version mismatches can trigger errors. This option forces those discrepancies to be ignored, which may help in experimental environments but can also cause unstable behavior.</p><div class="language-Java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Dfml.ignorePatchDiscrepancies</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">True</span></span></code></pre></div><h4 id="disable-log4j2-message-lookups" tabindex="-1">Disable Log4j2 message lookups <a class="header-anchor" href="#disable-log4j2-message-lookups" aria-label="Permalink to &quot;Disable Log4j2 message lookups&quot;">​</a></h4><p>This is a mitigation for the Log4Shell vulnerability and prevents dangerous lookups such as <code>${jndi:...}</code> from being evaluated inside log messages.</p><div class="language-Java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Dlog4j2.formatMsgNoLookups</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><h4 id="set-the-initial-heap-percentage-used-by-the-young-generation" tabindex="-1">Set the initial heap percentage used by the young generation <a class="header-anchor" href="#set-the-initial-heap-percentage-used-by-the-young-generation" aria-label="Permalink to &quot;Set the initial heap percentage used by the young generation&quot;">​</a></h4><div class="language-Java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">XX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">G1NewSizePercent</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span></span></code></pre></div><h4 id="set-the-maximum-heap-percentage-the-young-generation-can-grow-to" tabindex="-1">Set the maximum heap percentage the young generation can grow to <a class="header-anchor" href="#set-the-maximum-heap-percentage-the-young-generation-can-grow-to" aria-label="Permalink to &quot;Set the maximum heap percentage the young generation can grow to&quot;">​</a></h4><div class="language-Java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">XX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">G1MaxNewSizePercent</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span></span></code></pre></div><h4 id="set-the-target-maximum-gc-pause-time-in-milliseconds" tabindex="-1">Set the target maximum GC pause time in milliseconds <a class="header-anchor" href="#set-the-target-maximum-gc-pause-time-in-milliseconds" aria-label="Permalink to &quot;Set the target maximum GC pause time in milliseconds&quot;">​</a></h4><p>G1 tries to keep each GC pause near this soft target by adjusting region and generation behavior.</p><div class="language-Java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">XX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">G1GCauseTimeMillis</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">200</span></span></code></pre></div><h4 id="control-the-mixed-gc-target-count" tabindex="-1">Control the mixed GC target count <a class="header-anchor" href="#control-the-mixed-gc-target-count" aria-label="Permalink to &quot;Control the mixed GC target count&quot;">​</a></h4><div class="language-Java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">XX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">G1MixedGCCountTarget</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span></span></code></pre></div><h3 id="java-25-and-later" tabindex="-1">Java 25 and later <a class="header-anchor" href="#java-25-and-later" aria-label="Permalink to &quot;Java 25 and later&quot;">​</a></h3><p>Compact object headers reduce object header size and can lower heap memory usage on Java 25 and later.</p><div class="language-Java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">XX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">UseCompactObjectHeaders</span></span></code></pre></div><h4 id="set-the-number-of-concurrent-gc-threads" tabindex="-1">Set the number of concurrent GC threads <a class="header-anchor" href="#set-the-number-of-concurrent-gc-threads" aria-label="Permalink to &quot;Set the number of concurrent GC threads&quot;">​</a></h4><p>Default: about one quarter of the available CPU cores.</p><div class="language-Java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">XX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ConcGCThreads</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">N</span></span></code></pre></div><h4 id="set-sensitivity-to-sudden-allocation-spikes" tabindex="-1">Set sensitivity to sudden allocation spikes <a class="header-anchor" href="#set-sensitivity-to-sudden-allocation-spikes" aria-label="Permalink to &quot;Set sensitivity to sudden allocation spikes&quot;">​</a></h4><p>Useful for modded servers where mob spawning, redstone activity, or chunk loading may create sudden memory pressure.</p><div class="language-Java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">XX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ZAllocationSpikeTolerance</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span></span></code></pre></div><h4 id="set-the-zgc-soft-heap-limit-below-xmx" tabindex="-1">Set the ZGC soft heap limit below <code>-Xmx</code> <a class="header-anchor" href="#set-the-zgc-soft-heap-limit-below-xmx" aria-label="Permalink to &quot;Set the ZGC soft heap limit below `-Xmx`&quot;">​</a></h4><p>ZGC will try to keep heap usage under this value and only use the full <code>-Xmx</code> limit when necessary.</p><div class="language-Java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">XX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SoftMaxHeapSize</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Xmx8G </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">XX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SoftMaxHeapSize</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">7G</span></span></code></pre></div><h4 id="touch-all-memory-pages-at-startup" tabindex="-1">Touch all memory pages at startup <a class="header-anchor" href="#touch-all-memory-pages-at-startup" aria-label="Permalink to &quot;Touch all memory pages at startup&quot;">​</a></h4><p>This reduces runtime allocation latency and avoids pause spikes caused by page faults, although startup becomes slower.</p><div class="language-Java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">XX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AlwaysPreTouch</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><h4 id="use-large-pages-carefully" tabindex="-1">Use large pages carefully <a class="header-anchor" href="#use-large-pages-carefully" aria-label="Permalink to &quot;Use large pages carefully&quot;">​</a></h4><p>Large pages can improve throughput and reduce CPU cost, but JVM startup may fail if the operating system cannot provide suitable memory regions.</p><p>Known workarounds:</p><ol><li>Make sure the operating system has enough clean memory.</li><li>On virtual machines, adjust memory allocation strategy if needed.</li><li>On physical machines, verify that enough RAM is available.</li><li>Consider transparent huge pages instead.</li></ol><div class="language-Java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">XX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">UseTransparentHugePages</span></span></code></pre></div><div class="language-Java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">XX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">UseLargePages</span></span></code></pre></div></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><h4 id="arguments-you-must-not-use" tabindex="-1">Arguments you must not use <a class="header-anchor" href="#arguments-you-must-not-use" aria-label="Permalink to &quot;Arguments you must not use&quot;">​</a></h4><p>With Java 25+ ZGC, do not set <code>-XX:ZCollectionInterval</code>. ZGC already contains its own scheduling strategy, and forcing collection intervals can cause severe periodic lag spikes.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><h4 id="heap-size-examples" tabindex="-1">Heap size examples <a class="header-anchor" href="#heap-size-examples" aria-label="Permalink to &quot;Heap size examples&quot;">​</a></h4><p><code>-Xmx</code> is the maximum heap size and <code>-Xms</code> is the initial heap size.</p><p>Important notes:</p><ol><li><code>-Xms</code> must be less than or equal to <code>-Xmx</code>.</li><li>Use practical values such as 1G, 2G, 4G, 8G, 16G, 32G, or 64G when possible.</li><li>Do not set memory options in both the launcher and the instance JVM configuration at the same time.</li></ol><p>Wrong example:</p><div class="language-Java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Xms8G </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Xmx1G</span></span></code></pre></div><p>Correct example:</p><div class="language-Java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Xms8G </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Xmx8G</span></span></code></pre></div></div>',53)])])}const g=s(n,[["render",l]]);export{k as __pageData,g as default};
